            if (!reader.TryReadInt32(out var health, out error))
            {
                return false;
            }

            if (!reader.TryReadInt32(out var maximumHealth, out error))
            {
                return false;
            }

            if (!reader.TryReadInt32(out var mana, out error))
            {
                return false;
            }

            if (!reader.TryReadInt32(out var maximumMana, out error))
            {
                return false;
            }

            if (!reader.TryReadByte(out var lifeStateByte, out error))
            {
                return false;
            }

            var lifeState = (RealtimeCombatLifeState)lifeStateByte;

            if (!reader.TryReadUInt32(out var lifeSequence, out error))
            {
                return false;
            }

            if (!reader.TryReadUInt32(out var respawnTick, out error))
            {
                return false;
            }

            if (!reader.TryReadBoolean(out var inCombat, out error))
            {
                return false;
            }

            if (!reader.TryReadUInt64(out var targetEntityId, out error))
            {
                return false;
            }

            if (!reader.TryReadByte(out var attackStatusByte, out error))
            {
                return false;
            }

            var attackStatus = (RealtimeCombatAttackStatus)attackStatusByte;

            if (!reader.TryReadUInt32(out var nextAttackTick, out error))
            {
                return false;
            }

            if (!reader.TryReadUInt32(out var lockoutEndTick, out error))
            {
                return false;
            }

            if (!reader.TryReadGuid(out var ammunitionItemInstanceId, out error))
            {
                return false;
            }

            if (!reader.TryReadInt32(out var ammunitionQuantity, out error))
            {
                return false;
            }

            value = new RealtimeOwnerCombatState(stateRevision, serverTick, health, maximumHealth, mana, maximumMana, lifeState, lifeSequence, respawnTick, inCombat, targetEntityId, attackStatus, nextAttackTick, lockoutEndTick, ammunitionItemInstanceId, ammunitionQuantity);
            return true;
        }

        private static bool IsValidOwnerCombatState(RealtimeOwnerCombatState value)
        {
            if (value == null
                || value.StateRevision < 1
                || value.Health < 0
                || value.MaximumHealth < 1
                || value.Mana < 0
                || value.MaximumMana < 0
                || !IsDefined(value.LifeState)
                || !IsDefined(value.AttackStatus)
                || value.AmmunitionQuantity < 0)
            {
                return false;
            }

            return SatisfiesRules(value);
        }

        private static void WriteCombatEvent(ref PacketWriter writer, RealtimeCombatEvent value)
        {
            writer.WriteByte((byte)value.Kind);
            writer.WriteUInt64(value.SourceEntityId);
            writer.WriteUInt64(value.TargetEntityId);
            writer.WriteUInt32(value.ImpactTick);
            writer.WriteInt32(value.Damage);
            writer.WriteByte((byte)value.DamageType);
            writer.WriteInt32(value.HealthAfter);
            writer.WriteByte((byte)value.AttackStyle);
        }

        private static bool TryReadCombatEvent(ref PacketReader reader, out RealtimeCombatEvent value, out string error)
        {
            value = null;
            if (!reader.TryReadByte(out var kindByte, out error))
            {
                return false;
            }

            var kind = (RealtimeCombatEventKind)kindByte;

            if (!reader.TryReadUInt64(out var sourceEntityId, out error))
            {
                return false;
            }

            if (!reader.TryReadUInt64(out var targetEntityId, out error))
            {
                return false;
            }

            if (!reader.TryReadUInt32(out var impactTick, out error))
            {
                return false;
            }

            if (!reader.TryReadInt32(out var damage, out error))
            {
                return false;
            }

            if (!reader.TryReadByte(out var damageTypeByte, out error))
            {
                return false;
            }

            var damageType = (RealtimeCombatDamageType)damageTypeByte;

            if (!reader.TryReadInt32(out var healthAfter, out error))
            {
                return false;
            }

            if (!reader.TryReadByte(out var attackStyleByte, out error))
            {
                return false;
            }

            var attackStyle = (RealtimeCombatAttackStyle)attackStyleByte;

            value = new RealtimeCombatEvent(kind, sourceEntityId, targetEntityId, impactTick, damage, damageType, healthAfter, attackStyle);
            return true;
        }

        private static bool IsValidCombatEvent(RealtimeCombatEvent value)
        {
            if (value == null
                || !IsDefined(value.Kind)
                || value.TargetEntityId < 1
                || value.Damage < 0
                || !IsDefined(value.DamageType)
                || value.HealthAfter < 0
                || !IsDefined(value.AttackStyle))
            {
                return false;
            }

            return SatisfiesRules(value);
        }

        private static bool IsDefined(RealtimeCombatEventKind value)
        {
            return (byte)value >= 1 && (byte)value <= 3;
        }

        private static bool IsDefined(RealtimeCombatDamageType value)
        {
            return (byte)value >= 1 && (byte)value <= 5;
        }

        private static bool IsDefined(RealtimeCombatAttackStyle value)
        {
            return (byte)value >= 1 && (byte)value <= 3;
        }

        private static bool IsDefined(RealtimeCombatIntentKind value)
        {
            return (byte)value >= 1 && (byte)value <= 2;
        }

        private static bool IsDefined(RealtimeCombatLifeState value)
        {
            return (byte)value >= 1 && (byte)value <= 3;
        }

        private static bool IsDefined(RealtimeCombatAttackStatus value)
        {
            return (byte)value >= 1 && (byte)value <= 11;
        }
    }
}
